Lemma land64_mod'' : forall x, Z.land x 18446744073709551615 = x mod 2^64.
Proof. intros x. change 18446744073709551615 with (Z.ones 64). rewrite Z.land_ones by lia. reflexivity. Qed.
Lemma swrap32_small' : forall z, -2^31 <= z < 2^31 -> bv_swrap 32 z = z.
Proof. intros z H. apply bv_swrap_small. replace (bv_half_modulus 32) with (2^31) by (vm_compute; reflexivity). lia. Qed.
Lemma land_ones_l : forall x, 0 <= x < 2^64 -> Z.land 18446744073709551615 x = x.
Proof. intros x Hx. rewrite Z.land_comm, land64_mod''. apply Z.mod_small. lia. Qed.

