(* [comment removed for export] *)
Definition req_tail_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P lo : Z) (h : hdrv) (ver : Z) (m1 : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m2,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m2 (seg_rom asegs)
    /\ munch [(lo, bv_unsigned sp); (P + O_PR_HDR, P + O_PR_HDR + 40)]%Z m1 m2 /\ wmono asegs m1 m2 /\ mem_inv asegs m2
    /\ stk asegs m2 lo (bv_unsigned sp)
    /\ rw_cells asegs m2 (P + O_PR_HDR) (HdrCells (mkHV (hv_mp h) (hv_ml h) (hv_tp h) (hv_tl h) ver (hv_vb h))).

Definition req_tail_stmt : Prop :=
  forall pcv rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s1x s2x s3x s5x s6x s0v s1v s2v s3v s4v s5v s6v s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (P lo ver : Z) (h : hdrv),
  (pcv = Z_to_bv 64 AWK_RET_RS \/ pcv = ret_pc (Z_to_bv 64 AWK_RET_RS)) ->
  rw_cells asegs m1 (bv_unsigned sp + -16) [C8 (wz 0); C8 ra] ->
  rw_cells asegs m1 (bv_unsigned sp + -80) (wk_frame s0v s1v s2v s3v s4v s5v s6v) ->
  rw_cells asegs m1 (P + O_PR_HDR) (HdrCells h) -> 0 <= hv_ver h < 2^32 ->
  stk asegs m1 lo (bv_unsigned sp + -80) ->
  0 <= P -> P + 256 <= aceil -> P mod 8 = 0 -> aapp P 256 -> accessible m1 P 256 ->
  aceil <= lo -> lo + 80 <= bv_unsigned sp -> (ver = 10 \/ ver = 11) ->
  mem_inv asegs m1 -> ACONST m1 -> bv_unsigned ra mod 2 = 0 ->
  evt asegs (req_tail_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7 s8 s9 s10 s11 F fc P lo h ver m1)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2 (wz ver) s1x a0 a1 a2 a3 a4 a5 a6 a7
              s2x s3x (wz (P + 80)) s5x s6x s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F pcv fc None m1 (seg_rom asegs)).
